def qa(s,forms):
 typ='cross_text_synthesis' if s.get('pair') and s['id'].endswith('p04') else 'summary';pr='Compare les deux positions sur l’adaptation culturelle.' if typ=='cross_text_synthesis' else 'Résume la logique critique du passage.';an=s.get('across',s['asummary'])
 return [('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('inference',s['qinfer'],s['ainfer'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('argument_relation',s['qrelation'],s['arelation'],[forms[3]]),('stance','Quelle position critique l’auteur adopte-t-il ?',s['astance'],[forms[0],forms[3]]),(typ,pr,an,[forms[1],forms[2]])]+[('vocabulary_in_context',f'Quel rôle critique joue « {f} » ?',USE[f],[f]) for f in forms]
def mk(s,forms,reviews,prior,deck,lo,hi,theme):
 ps=list(s['paras']);ps[1]+=' '+' '.join(USE[f] for f in forms);ps[2]+=' '+bridge(reviews);ps,text=fit(ps,lo,hi);P=base.prior(prior);new=[base.nt(f,text,deck) for f in forms];rev=[base.rev(f,P) for f in reviews];ids={t['form']:t['id'] for t in new+rev};q,a=base.qa(qa(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C1','unit':7,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':'instructional','genre':s['genre'],'domains':['educational','public'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'new','description':'qualify interpretation, focalization, metaphor and cultural reference'}],'discourse_targets':[{'id':s['id']+'-d1','role':'new','description':'move from textual evidence to interpretation, counterreading, scope and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C1 Unit07 literary/cultural criticism.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Fictional literary-critical material.']},'paired_text_group':s.get('pair'),'prerequisites':['French C1 Unit06'],'difficulty_notes_internal':'C1 literary inference, cultural context and competing interpretation.','reader_tags':['unit_role:instructional','generation_batch','french_c1_u07']}
def specs():return [
 {'id':'fr-c1-u07-p01','seq':37,'title':'Mémoire racontée, mémoire reconstruite','genre':'close-reading style prose','topics':['memory','focalization'],'paras':["Un récit fictif s’ouvre sur une scène d’enfance racontée plusieurs décennies plus tard. Le narrateur affirme se rappeler avec précision une maison, une voix et une décision familiale, mais certains détails changent lorsqu’une seconde scène revient sur le même événement. La critique ne traite pas cette variation comme une erreur à corriger automatiquement : elle demande ce que la reconstruction du passé révèle sur le présent du narrateur.","Le dossier compare les éléments stables et les éléments mobiles. Les lieux restent reconnaissables, tandis que les motivations attribuées aux adultes deviennent plus nuancées. Cette asymétrie suggère que le récit ne cherche pas seulement à récupérer des faits; il met en scène une conscience qui réévalue ce qu’elle croyait comprendre.","Une lecture concurrente affirme que les différences ne signalent aucune stratégie : elles pourraient simplement imiter l’imprécision ordinaire de la mémoire. L’analyse prend cette objection au sérieux et cherche si les variations apparaissent aux moments où la responsabilité, la honte ou le pardon sont reconsidérés. Si elles sont structurées autour de ces conflits, l’hypothèse formelle gagne en force.","La conclusion reste limitée : le lecteur ne peut pas connaître le passé fictif indépendamment des versions données par le récit. Il peut toutefois analyser comment ces versions se corrigent, quels détails deviennent incertains et quelle transformation du narrateur accompagne cette incertitude."],'qclaim':'Quelle thèse organise la lecture de la mémoire ?','aclaim':'Les variations du souvenir peuvent mettre en scène une réévaluation présente plutôt qu’une simple copie imparfaite du passé.','qinfer':'Pourquoi comparer éléments stables et mobiles ?','ainfer':'Pour voir si la variation suit des conflits interprétatifs précis plutôt qu’un hasard général.','qassume':'Que suppose une lecture formelle des contradictions ?','aassume':'Que leur distribution dans le récit est liée à des thèmes ou décisions et n’est pas aléatoire.','qrelation':'Comment le texte traite-t-il l’explication par l’imprécision ordinaire ?','arelation':'Il l’utilise comme contrelecture et cherche des régularités qui permettraient de la distinguer.','astance':'Lire la mémoire comme construction textuelle tout en limitant les inférences sur un passé inaccessible.','asummary':'La critique suit les variations du souvenir pour analyser la transformation du narrateur sans prétendre reconstruire un passé extérieur au texte.'},
 {'id':'fr-c1-u07-p02','seq':38,'title':'Une émotion visible ne donne pas encore le ton du récit','genre':'critical essay','topics':['tone','emotion'],'paras':["Dans une nouvelle fictive, une scène passe rapidement d’un repas joyeux à une dispute. Un personnage rit au moment où un autre annonce une mauvaise nouvelle, puis quitte la pièce en silence. Une lecture immédiate pourrait qualifier le personnage d’insensible, mais la focalisation limite ce que le lecteur sait de ses raisons.","Le dossier distingue émotion représentée et ton narratif. Le geste du personnage, les commentaires du narrateur et le rythme des phrases peuvent aller dans des directions différentes. Une réaction qui semble cruelle dans le résumé peut devenir gêne ou défense lorsque le texte ralentit sur les hésitations qui la précèdent.","Le contreargument affirme qu’une lecture trop charitable efface la violence sociale de la scène. La critique répond qu’expliquer une ambiguïté ne signifie pas excuser le personnage. Elle compare donc l’effet du geste sur les autres, les indices d’intention et la manière dont le récit distribue la sympathie.","La conclusion refuse un diagnostic unique. Le ton résulte d’une relation entre actions, voix narrative, rythme et attentes du lecteur. Une émotion explicitement nommée reste importante, mais elle n’annule pas les tensions produites par les autres niveaux du texte."],'qclaim':'Quelle distinction centrale organise le passage ?','aclaim':'Il faut distinguer l’émotion montrée par un personnage du ton construit par l’ensemble de la narration.','qinfer':'Pourquoi le rire n’impose-t-il pas une seule lecture ?','ainfer':'Parce que focalisation, hésitation et contexte peuvent lui donner plusieurs fonctions.','qassume':'Que suppose une interprétation du ton ?','aassume':'Qu’elle relie plusieurs indices formels et narratifs plutôt qu’un geste isolé.','qrelation':'Comment le texte répond-il à l’objection d’une lecture trop charitable ?','arelation':'Il distingue explication et excuse puis examine les effets du geste et la distribution de la sympathie.','astance':'Interpréter le ton par convergence d’indices sans réduire le personnage à une émotion visible.','asummary':'Le ton se construit à travers la relation entre geste, focalisation, rythme, effet social et voix narrative.'},
 {'id':'fr-c1-u07-p03','seq':39,'title':'Point de vue A : préserver la distance des symboles historiques','genre':'paired viewpoints','topics':['adaptation','historical imagery'],'pair':PAIR,'paras':["Le premier point de vue critique une adaptation fictive qui transforme une légende hiérarchique en spectacle contemporain. Selon cette lecture, les titres et figures historiques ne sont pas de simples accessoires visuels : ils organisent des relations de dépendance, d’obéissance et de prestige que l’adaptation risque d’effacer lorsqu’elle conserve l’image sans le conflit social.","La critique propose donc de préserver une certaine distance. Le public peut apprécier l’énergie d’une adaptation tout en rencontrant les différences de valeurs et d’institutions qui rendent le matériau ancien réellement étranger. Une œuvre qui traduit tout en catégories contemporaines risque de rendre le passé trop facile à reconnaître.","L’objection affirme que toute reconstitution est déjà une sélection moderne. Le point de vue A l’accepte, mais demande que les choix soient visibles. Une adaptation peut simplifier une structure sociale si elle montre ce qu’elle transforme et laisse subsister des tensions qui empêchent le symbole de devenir une décoration neutre.","La conclusion défend une fidélité critique plutôt que littérale. Il ne s’agit pas de reproduire chaque détail historique, mais de conserver les problèmes de pouvoir, de rang et de dépendance qui donnent aux images leur poids narratif."],'qclaim':'Quelle priorité défend le point de vue A ?','aclaim':'Préserver la distance et les conflits sociaux portés par les symboles historiques plutôt que de garder seulement leur apparence.','qinfer':'Pourquoi une adaptation très familière peut-elle appauvrir le passé ?','ainfer':'Parce qu’elle peut traduire des institutions différentes en catégories contemporaines trop évidentes.','qassume':'Que suppose une fidélité critique ?','aassume':'Que l’adaptation identifie les relations ou tensions essentielles même si elle change des détails.','qrelation':'Comment le texte répond-il à l’idée que toute adaptation est moderne ?','arelation':'Il l’admet mais exige que les transformations soient visibles et interprétables.','astance':'Maintenir l’étrangeté pertinente du matériau historique sans exiger une copie littérale.','asummary':'L’adaptation peut changer la forme tout en conservant les conflits qui donnent sens aux symboles.'},
 {'id':'fr-c1-u07-p04','seq':40,'title':'Point de vue B : une tradition vit aussi par ses reprises','genre':'paired viewpoints','topics':['performance','living tradition'],'pair':PAIR,'paras':["Le second point de vue part du public et de la performance. Une histoire culturelle n’existe pas seulement dans des textes conservés; elle circule quand des groupes la racontent, la chantent, la jouent ou la déplacent vers de nouveaux contextes. Une reprise qui transforme fortement la forme peut donc révéler une continuité d’usage plutôt qu’une perte de fidélité.","Cette lecture observe qui participe, quels éléments sont repris et ce qui devient discutable pendant la performance. Une répétition collective peut faire émerger des significations absentes d’une lecture silencieuse. Le changement n’est pas automatiquement une trahison : il peut rendre visible ce qu’une communauté choisit de conserver.","Le contreargument du point de vue A reste sérieux : une fête esthétique peut neutraliser la violence ou la hiérarchie du matériau ancien. Le point de vue B répond que la solution est d’analyser la transformation, non de l’interdire. Une adaptation peut juxtaposer plaisir et critique, par exemple en laissant un refrain séduisant entrer en conflit avec les conséquences racontées.","La conclusion défend une tradition observable dans ses usages. La fidélité se mesure alors par les relations maintenues, les questions transmises et les désaccords ouverts, plutôt que par l’identité de chaque détail de surface."],'qclaim':'Quelle priorité défend le point de vue B ?','aclaim':'Évaluer une tradition par les usages et relations qu’une communauté réactive, pas seulement par la conservation littérale de la forme.','qinfer':'Pourquoi une transformation peut-elle constituer une continuité ?','ainfer':'Parce qu’elle peut maintenir des questions, relations ou pratiques collectives malgré un changement de forme.','qassume':'Que suppose une adaptation critique réussie ?','aassume':'Qu’elle rende visibles les conséquences et tensions au lieu de transformer tout le matériau en décor agréable.','qrelation':'Comment le texte répond-il à l’objection de neutralisation esthétique ?','arelation':'Il propose d’analyser les contradictions internes de la performance et la manière dont elle conserve ou critique les tensions.','astance':'Traiter la tradition comme une pratique réinterprétée et contestable.','asummary':'Une reprise peut être culturellement fidèle par les relations et questions qu’elle maintient même si sa surface change.','across':'A insiste sur la distance historique et les conflits qu’une adaptation ne doit pas effacer; B insiste sur les usages collectifs capables de transformer la forme tout en maintenant des questions et relations.'},
 {'id':'fr-c1-u07-p05','seq':41,'title':'Lire les espaces comme une structure, pas comme un dictionnaire de symboles','genre':'close-reading style prose','topics':['space','metaphor','form'],'paras':["Un roman fictif oppose régulièrement intérieur et extérieur : des conversations décisives ont lieu dans des espaces étroits, tandis que les déplacements importants traversent des seuils ou des places ouvertes. La tentation serait d’attribuer immédiatement une signification fixe à chaque espace. La critique choisit plutôt de suivre les transformations de cette opposition.","Le dossier cartographie les scènes, les verbes de mouvement et les changements de point de vue. Il observe quand un espace protège, enferme, expose ou permet de voir autrement. La même pièce peut ainsi fonctionner différemment selon le personnage qui y entre et selon ce qu’il sait à ce moment.","Une lecture concurrente affirme que ces répétitions sont simplement nécessaires au décor. L’analyse cherche alors des variations structurées : si les changements spatiaux coïncident avec des décisions, des révélations ou des inversions de pouvoir, leur fonction formelle devient plus plausible. Si les lieux se distribuent sans relation, l’interprétation doit être réduite.","La conclusion définit la métaphore comme une relation construite, non comme une équivalence automatique. L’espace devient critique lorsque le texte produit assez de correspondances pour que le lecteur compare orientation physique, accès à l’information et position sociale."],'qclaim':'Quelle méthode de lecture spatiale est proposée ?','aclaim':'Suivre les variations d’usage des espaces et leurs relations avec information, décision et pouvoir plutôt que donner un sens fixe à chaque lieu.','qinfer':'Pourquoi la même pièce peut-elle changer de fonction ?','ainfer':'Parce que personnage, information et relation sociale changent selon la scène.','qassume':'Que suppose une lecture métaphorique convaincante ?','aassume':'Plusieurs correspondances structurées entre espace et autres dimensions du récit.','qrelation':'Comment le texte traite-t-il l’explication par le simple décor ?','arelation':'Il cherche si les changements spatiaux coïncident systématiquement avec des transformations narratives.','astance':'Construire une interprétation spatiale révisable à partir de relations répétées.','asummary':'La forme spatiale devient interprétable lorsqu’elle organise de façon répétée mouvement, savoir et position sociale.'}]
def checkpoint(groups,deck,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]];ps=["Le checkpoint propose un extrait fictif où un narrateur revient sur une cérémonie ancienne qu’il avait d’abord décrite comme heureuse. Des années plus tard, il remarque un détail de décor, une réaction d’un proche et une phrase qu’il avait supprimée de sa première version. Le lecteur doit articuler mémoire, ton, contexte culturel, performance et structure spatiale sans convertir chaque élément en symbole certain.","La première lecture reconstruit la focalisation : quelles informations appartiennent au passé raconté, lesquelles viennent du narrateur actuel et lesquelles restent seulement supposées ? Cette séparation empêche la maturité du narrateur d’être projetée sur l’enfant qu’il décrit.","La seconde lecture formule deux hypothèses concurrentes. L’une voit la cérémonie comme une appartenance collective progressivement remise en question; l’autre y voit surtout un conflit familial que le décor culturel amplifie. Chaque hypothèse doit expliquer des détails différents et annoncer ce qui la rendrait moins plausible.","La synthèse retient une lecture provisoire et précise sa portée. Elle indique quels motifs sont suffisamment répétés, quelles références culturelles demandent du contexte et quel nouveau passage obligerait à réviser l’interprétation. La critique reste ainsi argumentative sans prétendre que le texte ne possède qu’un sens possible."];ps[1]+=' Révision cumulative : '+'; '.join(f'« {f} »' for f in forms)+'.';ps,text=fit(ps,lo,hi);P=base.prior(prior);rev=[base.rev(f,P) for f in forms];ids={t['form']:t['id'] for t in rev};items=[('main_claim','Quelle méthode générale organise le checkpoint ?','Construire une interprétation à partir de la focalisation, de motifs répétés, d’un contreargument et d’une condition de révision.',[forms[0]]),('inference','Pourquoi séparer narrateur actuel et enfant raconté ?','Pour éviter de projeter la compréhension présente sur la conscience passée.',[forms[1]]),('assumption','Que suppose une hypothèse sur la cérémonie ?','Qu’elle explique plusieurs détails indépendants et puisse être confrontée à une lecture concurrente.',[forms[8]]),('argument_relation','Comment deux lectures concurrentes sont-elles comparées ?','Par les détails que chacune explique et les passages qui la fragiliseraient.',[forms[12]]),('stance','Quelle attitude critique domine ?','Une lecture argumentée, contextuelle et révisable.',[forms[16]]),('summary','Résume le checkpoint.','Distinguer les niveaux de voix, tester des motifs et du contexte, comparer deux lectures et annoncer la portée de la conclusion.',[forms[19]]),('vocabulary_in_context',f'Quel rôle joue « {forms[3]} » ?',USE[forms[3]],[forms[3]]),('vocabulary_in_context',f'Comment interpréter « {forms[6]} » ?',USE[forms[6]],[forms[6]]),('vocabulary_in_context',f'Pourquoi « {forms[14]} » compte-t-il pour la réception ?',USE[forms[14]],[forms[14]]),('synthesis','Quelle règle peut être transférée à une autre œuvre ?','Une interprétation forte explique plusieurs indices, survit à une contrelecture sérieuse, limite sa portée et reste révisable.',[forms[10],forms[18]])];q,a=base.qa(items,ids)
 return {'id':'fr-c1-u07-p06','language':'fr','cefr':'C1','unit':7,'sequence':42,'revision':1,'title':'Checkpoint : interpréter sans figer le sens','passage_type':'checkpoint','genre':'critical essay','domains':['educational','public'],'topics':[theme,'cumulative interpretation'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c1-u07-p06-g1','role':'integration','description':'integrate focalization, qualification and interpretive scope'}],'discourse_targets':[{'id':'fr-c1-u07-p06-d1','role':'integration','description':'synthesize evidence, counterreading, cultural context and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C1 Unit07 zero-new checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Zero-new literary criticism checkpoint.']},'paired_text_group':None,'prerequisites':['French C1 Unit07 P01-P05'],'difficulty_notes_internal':'C1 cumulative literary interpretation.','reader_tags':['unit_role:checkpoint','generation_batch','french_c1_u07']}
def main():
 rows=[json.loads(x) for x in C1.read_text().splitlines() if x.strip()];lock=json.loads(LOCK.read_text());plan=json.loads(PLAN.read_text());sel=json.loads(SEL.read_text());c1=h(C1);b2=h(B2)
 if len(rows)!=36 or lock.get('status')!='PASS' or lock.get('c1_canonical_blob')!=c1 or lock.get('b2_canonical_blob')!=b2:raise AssertionError('Unit07 source mismatch')
 if plan.get('c1_source_blob')!=c1 or sel.get('c1_source_blob')!=c1:raise AssertionError('Unit07 plan/selection stale')
 groups=sel['passage_groups'];r6=lock['unit06_target_groups'];reviews={k:r6[k] for k in ['p01','p02','p03','p04','p05']};deck=base.deck();lo,hi=sel['word_band'];unit=[mk(s,groups[s['id'][-3:]],reviews[s['id'][-3:]],rows,deck,lo,hi,plan['theme']) for s in specs()];unit.append(checkpoint(groups,deck,lo,hi,plan['theme'],rows+unit));V=Draft202012Validator(json.loads(SCHEMA.read_text()))
 for r in unit:
  errs=sorted(V.iter_errors(r),key=lambda e:list(e.path))
  if errs:raise AssertionError(f"{r['id']}: schema {[e.message for e in errs[:8]]}")
